143	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
144	  let quotesSoFar = 0;
145	  const results = scenario.steps.map((step) => {
146	    if (step.op === "quote") {
147	      const result = quote(step.items, scenario.customer, quotesSoFar);
148	      quotesSoFar += 1;
149	      return result;
150	    }
151	    throw new Error("claim steps are not implemented yet");
152	  });
153	  return { results };
154	};
