/**
 * Steps are not independent: each one is answered in the light of the steps before it,
 * so the scenario is walked as a fold that threads what has happened so far.
 */
interface ScenarioState {
  quotesSoFar: number;
}

const INITIAL_STATE: ScenarioState = { quotesSoFar: 0 };

const applyStep = (
  state: ScenarioState,
  step: Step,
  customer: Customer,
): { state: ScenarioState; result: Result } => {
  if (step.op === "quote") {
    return {
      state: { quotesSoFar: state.quotesSoFar + 1 },
      result: quote(step.items, customer, state.quotesSoFar),
    };
  }
  throw new Error("claim steps are not implemented yet");
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => {
  const { results } = scenario.steps.reduce(
    ({ state, results }, step) => {
      const stepOutcome = applyStep(state, step, scenario.customer);
      return { state: stepOutcome.state, results: [...results, stepOutcome.result] };
    },
    { state: INITIAL_STATE, results: [] as Result[] },
  );
  return { results };
};

